/* ---------- raccourcis étendus + mode vim ---------- */
const CHORD={h:"home",c:"cmd",j:"twin",o:"coach",p:"prog",z:"zen",l:"tl",f:"flow",m:"market",y:"heat",s:"sem",e:"collab",t:"studio",k:"keys",a:"agenda",b:"mail",n:"notes",d:"day",r:"crm",i:"assist",v:"vac",u:"subs",x:"fin"};
let vimBar=null,vimBuf="",vimCnt="",vimMode="normal",chordT=0,chordOn=false,cmdHist=[],helpEl=null;
function setVim(on){E().vim=on;A.save();if(on){if(!vimBar){vimBar=document.createElement("div");vimBar.className="ep-vim";vimBar.setAttribute("aria-live","polite");document.body.appendChild(vimBar)}vimPaint();toast("Mode vim activé : Alt+V pour quitter, ? pour l'aide")}else{vimBar&&vimBar.remove();vimBar=null;toast("Mode vim désactivé")}}
function vimPaint(){if(!vimBar)return;vimBar.innerHTML=`<b class="${vimMode}">-- ${vimMode==="normal"?"NORMAL":vimMode==="insert"?"INSERTION":"COMMANDE"} --</b><span>${esc(vimBuf||vimCnt)}</span><em>${esc(A.S.tab)} · niv.${A.lvl()}</em>`}
function scrollBy(dy){scrollBy_(dy)}function scrollBy_(dy){window.scrollBy({top:dy,behavior:reduce()?"auto":"smooth"})}
function tabStep(d){const ids=TABS.map(t=>t[0]);const i=ids.indexOf(A.S.tab);go(ids[(i+d+ids.length)%ids.length],true);$("#demo").scrollIntoView({block:"start"})}
function findTab(q){q=flat(q).trim();if(!q)return null;let t=TABS.find(t=>t[0]===q)||TABS.find(t=>flat(t[2]).startsWith(q))||TABS.find(t=>flat(t[2]).includes(q));return t&&t[0]}
function runEx(c){c=c.trim();if(!c)return;cmdHist.push(c);const[a,...r]=c.split(/\s+/),arg=r.join(" ");
 switch(a){case"q":case"q!":case"quit":closeOver();break;case"w":A.save();toast("Enregistré (localStorage)");break;case"wq":A.save();closeOver();toast("Enregistré");break;
 case"go":case"e":case"b":case"tab":{const t=findTab(arg);if(t)go(t,true);else toast("Section introuvable : "+arg);break}
 case"theme":A.S.theme=A.S.theme==="dark"?"light":"dark";A.save();A.render();break;case"dark":A.S.theme="dark";A.save();A.render();break;case"light":A.S.theme="light";A.save();A.render();break;
 case"zen":go("zen",true);setTimeout(()=>ACT.ep_zenGo&&ACT.ep_zenGo(),150);break;case"help":case"h":helpOpen();break;case"xp":toast("Niveau "+A.lvl()+" · "+A.S.xp+" XP · "+lt(A.lvl()));break;
 case"undo":A.undo();break;case"redo":A.redo();break;case"vim":if(arg==="off")setVim(false);break;case"intro":intro(true);break;case"fx":thSet({fx:FXN.find(f=>f[0]===flat(arg))?flat(arg):"aurore"});break;case"search":A.openSearch();break;
 case"set":if(/nu|number/.test(arg))toast("Pas de numéros de ligne ici, mais bel essai 😉");break;
 default:toast("Commande inconnue : :"+a+" (essaie :help)")}}
function closeOver(){if(zenEl&&zenClose)zenClose();if(introEl)introEl.querySelector("#introSkip").click();$$("dialog[open]").forEach(d=>d.close());if(helpEl){helpEl.remove();helpEl=null}}
function helpOpen(){if(helpEl){helpEl.remove();helpEl=null;return}helpEl=document.createElement("div");helpEl.className="ep-help";helpEl.setAttribute("role","dialog");helpEl.setAttribute("aria-label","Aide des raccourcis");helpEl.innerHTML=`<div class="card"><div class="row b"><h3 style="margin:0">⌨️ Raccourcis</h3><button class="btn sm" data-act="ep_help">Fermer (Échap)</button></div><div class="ep-keys">${keysHtml()}</div></div>`;document.body.appendChild(helpEl);helpEl.addEventListener("click",e=>{if(e.target===helpEl)helpOpen()})}
ACT.ep_help=()=>{helpEl&&helpEl.remove();helpEl=null};
const kb=k=>`<kbd>${k}</kbd>`;
function keysHtml(){return`<div><h4>Partout</h4><p>${kb("Ctrl")}+${kb("K")} palette · ${kb("Ctrl")}+${kb("Z")} annuler · ${kb("T")} thème · ${kb("?")} cette aide · ${kb("Alt")}+${kb("V")} mode vim · ${kb("Alt")}+${kb("1")}…${kb("9")} sections épiques</p></div>
<div><h4>Aller à (touche ${kb("g")} puis…)</h4><p>${Object.entries(CHORD).map(([k,t])=>`${kb("g")} ${kb(k)} ${esc((TABS.find(x=>x[0]===t)||[0,0,t])[2])}`).join(" · ")}</p></div>
<div><h4>Mode vim (normal)</h4><p>${kb("j")}/${kb("k")} défiler (précède d'un nombre pour répéter) · ${kb("h")}/${kb("l")} section précédente/suivante · ${kb("gg")}/${kb("G")} haut/bas · ${kb("Ctrl")}+${kb("d")}/${kb("u")} demi-page · ${kb("/")} recherche · ${kb(":")} ligne de commande · ${kb("i")} focus sur le premier champ · ${kb("u")} annuler · ${kb("Ctrl")}+${kb("r")} rétablir · ${kb("zt")} haut de la section · ${kb("Échap")} retour au mode normal</p></div>
<div><h4>Commandes ${kb(":")}</h4><p>${[":go cmd",":q",":w",":theme",":dark",":light",":zen",":xp",":fx grille",":intro",":undo",":help",":vim off"].map(c=>`<code>${c}</code>`).join(" ")}</p></div>`}
V.keys=()=>hd("⌨️","Raccourcis et mode vim","Navigue sans souris : accords « g », mode vim complet et ligne de commande.")+
 `<div class="card"><div class="row b"><div><b>Mode vim</b><div class="sub" style="margin:0">${E().vim?"Activé : regarde la barre en bas de l'écran.":"Désactivé. Active-le pour naviguer avec j, k, h, l, gg, G, / et :."}</div></div><button class="btn p" data-act="ep_vimtoggle">${E().vim?"Désactiver":"Activer"} le mode vim</button></div></div>
 <div class="card ep-keys" style="margin-top:12px">${keysHtml()}</div><div class="card" style="margin-top:12px"><b>Terrain de jeu</b><p class="sub">Active le mode vim, puis essaie : ${kb("j")} ${kb("j")} ${kb("k")}, ${kb("g")}${kb("g")}, ${kb(":")} <code>go zen</code> ${kb("Entrée")}.</p><input class="ep-vimin" placeholder="Champ de texte : tape i pour entrer ici, Échap pour sortir" aria-label="Terrain de jeu vim"></div>`;
ACT.ep_vimtoggle=()=>{setVim(!E().vim);A.render()};INIT.keys=()=>{};
let cmdEl=null;
function openCmd(pre=""){vimMode="command";vimPaint();if(cmdEl)cmdEl.remove();cmdEl=document.createElement("div");cmdEl.className="ep-cmdl";cmdEl.innerHTML=`<span>:</span><input aria-label="Ligne de commande vim" autocomplete="off" spellcheck="false" value="${esc(pre)}"><div class="ep-cmdh"></div>`;document.body.appendChild(cmdEl);const i=$("input",cmdEl),hint=$(".ep-cmdh",cmdEl);i.focus();let hi=cmdHist.length;
 const upd=()=>{const q=i.value.trim();const m=/^(go|e|b|tab)\s+(.*)$/.exec(q);hint.textContent=m?TABS.filter(t=>flat(t[0]+" "+t[2]).includes(flat(m[2]))).slice(0,5).map(t=>t[0]).join(" · "):""};i.addEventListener("input",upd);
 i.addEventListener("keydown",e=>{e.stopPropagation();if(e.key==="Escape"){endCmd()}else if(e.key==="Enter"){const v=i.value;endCmd();runEx(v)}else if(e.key==="ArrowUp"){hi=Math.max(0,hi-1);i.value=cmdHist[hi]||""}else if(e.key==="ArrowDown"){hi=Math.min(cmdHist.length,hi+1);i.value=cmdHist[hi]||""}else if(e.key==="Tab"){e.preventDefault();const m=/^(go|e|b|tab)\s+(.*)$/.exec(i.value);if(m){const t=findTab(m[2]);if(t)i.value=m[1]+" "+t}}})}
function endCmd(){cmdEl&&cmdEl.remove();cmdEl=null;vimMode="normal";vimBuf="";vimPaint();if(document.activeElement&&document.activeElement.blur)document.activeElement.blur()}
window.addEventListener("keydown",e=>{
 if(introEl)return;
 if(e.altKey&&!e.ctrlKey&&!e.metaKey&&(e.key==="v"||e.key==="V"||e.code==="KeyV")){e.preventDefault();e.stopPropagation();setVim(!E().vim);return}
 if(e.altKey&&!e.ctrlKey&&!e.metaKey&&/^[1-9]$/.test(e.key)){const ep=EPIC_IDS[+e.key-1];if(ep){e.preventDefault();e.stopPropagation();go(ep)}return}
 const inField=/INPUT|TEXTAREA|SELECT/.test(document.activeElement.tagName)||document.activeElement.isContentEditable;
 if(e.key==="Escape"){if(helpEl){helpOpen();e.stopPropagation();return}if(inField&&E().vim&&!cmdEl){document.activeElement.blur();vimMode="normal";vimPaint();e.stopPropagation();return}if(!inField)vimBuf="",vimCnt="";return}
 if(inField||e.ctrlKey&&!E().vim||e.metaKey||(e.altKey)||$("#gsd").open||$("#nd").open)return;
 if(zenEl)return;
 const k=e.key;
 if(k==="?"){e.preventDefault();e.stopPropagation();helpOpen();return}
 if(chordOn){chordOn=false;clearTimeout(chordT);const t=CHORD[k];if(t&&!(E().vim&&k==="g")){e.preventDefault();e.stopPropagation();go(t,true);$("#demo").scrollIntoView({block:"start"});return}if(!(E().vim&&k==="g"))return}
 if(!E().vim){if(k==="g"&&!e.shiftKey){chordOn=true;clearTimeout(chordT);chordT=setTimeout(()=>chordOn=false,1200)}return}
 /* vim normal */
 if(e.ctrlKey&&!/^[durfb]$/.test(k))return;
 e.stopPropagation();inc("vim");
 if(e.ctrlKey){if(k==="d"){e.preventDefault();scrollBy(innerHeight/2)}else if(k==="u"){e.preventDefault();scrollBy(-innerHeight/2)}else if(k==="r"){e.preventDefault();A.redo()}else if(k==="f"){e.preventDefault();scrollBy(innerHeight*.9)}else if(k==="b"){e.preventDefault();scrollBy(-innerHeight*.9)}return}
 if(/^[0-9]$/.test(k)&&!(k==="0"&&!vimCnt)){e.preventDefault();vimCnt+=k;vimPaint();return}
 const n=Math.max(1,+vimCnt||1);const done=()=>{vimCnt="";vimBuf="";vimPaint()};
 if(vimBuf==="g"){e.preventDefault();if(k==="g"){window.scrollTo({top:0,behavior:reduce()?"auto":"smooth"});done();return}if(CHORD[k]){go(CHORD[k],true);$("#demo").scrollIntoView({block:"start"});done();return}done();return}
 if(vimBuf==="z"){e.preventDefault();if(k==="t"){$("#main").scrollIntoView({block:"start"})}else if(k==="z"){$("#main").scrollIntoView({block:"center"})}done();return}
 switch(k){case"j":case"ArrowDown":e.preventDefault();scrollBy(70*n);done();break;case"k":case"ArrowUp":e.preventDefault();scrollBy(-70*n);done();break;
  case"l":case"ArrowRight":e.preventDefault();for(let i=0;i<n;i++)tabStep(1);done();break;case"h":case"ArrowLeft":e.preventDefault();for(let i=0;i<n;i++)tabStep(-1);done();break;
  case"G":e.preventDefault();window.scrollTo({top:document.body.scrollHeight,behavior:reduce()?"auto":"smooth"});done();break;
  case"g":e.preventDefault();vimBuf="g";vimPaint();break;case"z":e.preventDefault();vimBuf="z";vimPaint();break;
  case"/":e.preventDefault();A.openSearch();done();break;case":":e.preventDefault();openCmd();break;
  case"i":case"a":case"I":case"A":{e.preventDefault();const f=$$("#main input:not([type=checkbox]):not([type=range]),#main textarea").find(x=>x.offsetParent);if(f){f.focus();vimMode="insert";vimPaint()}else toast("Aucun champ de texte ici");done();break}
  case"u":e.preventDefault();for(let i=0;i<n;i++)A.undo();done();break;case"x":e.preventDefault();done();break;
  case"Escape":done();break;default:e.preventDefault();done()}
},true);
document.addEventListener("focusout",()=>{if(E().vim&&vimMode==="insert"&&!/INPUT|TEXTAREA/.test((document.activeElement||{}).tagName||"")){vimMode="normal";vimPaint()}});
/* ---------- concentration immersive : sons générés (WebAudio) + particules ---------- */
let zenEl=null,zenClose=null;
const ZL=[["pluie","🌧️","Pluie"],["vagues","🌊","Vagues"],["vent","🍃","Vent"],["feu","🔥","Feu de camp"],["nuit","🦗","Nuit d'été"],["drone","🕉️","Drone méditatif"],["binaural","🎧","Ondes 40 Hz (écouteurs)"],["cafe","☕","Café bondé (extension)"],["orage","⛈️","Orage lointain (extension)"]];
