function semSearch(q){const qv=vec(q);const ds=docs();const out=ds.map(d=>{let s=cosM(qv.cf,d.v.cf)*.55+cosM(qv.tf,d.v.tf)*.55;const ql=flat(q);if(ql.length>3&&flat(d.t+" "+d.x).includes(ql))s+=.5;const shared=Object.keys(qv.cf).filter(c=>d.v.cf[c]);return{...d,s,cons:shared,tk:Object.keys(qv.tf).filter(t=>d.v.tf[t])}}).filter(r=>r.s>.06).sort((a,b)=>b.s-a.s);return{out:out.slice(0,12),all:ds,qv}}
